import functools
import threading
from typing import Callable, Any, Union

def cached(cache, key: Union[Callable[..., Any], str] = hash, lock: threading.Lock = None) -> Callable[..., Any]:
    """
    Returns a decorator function that saves the results in the cache
    """
    def decorator(func: Callable[..., Any]) -> Callable[..., Any]:
        @functools.wraps(func)
        def wrapper(*args, **kwargs) -> Any:
            key_arg = key(*args, **kwargs)
            if lock:
                lock.acquire()
            try:
                result = cache.get(key_arg)
                if result is None:
                    result = func(*args, **kwargs)
                    cache.set(key_arg, result)
                return result
            finally:
                if lock:
                    lock.release()
        return wrapper
    return decorator

