def split(s: str, platform: str = 'this') -> List[str]:
    if platform == 'this':
        platform = os.name

    if platform == 'nt':
        # Windows platform
        return re.split(r'\\', s)
    elif platform == 'posix':
        # Unix/Linux/Mac platform
        return re.split(r'/', s)
    else:
        raise ValueError(f"Unsupported platform: {platform}")

