import re
import datetime
from typing import Optional

def parse_frequency(frequency: str) -> Optional[datetime.timedelta]:
    """
    Parses a frequency string into a timedelta object.

    Args:
        frequency (str): The frequency string to parse.

    Returns:
        Optional[datetime.timedelta]: A timedelta object representing the frequency, or None if the input is 'always' or None.

    Raises:
        ValueError: If the unit in the frequency string is not recognized.
    """
    if frequency is None or frequency == 'always':
        return None

    # Regular expression to match the frequency pattern
    pattern = re.compile(r'^(\d+)\s*(seconds|minutes|hours|days|weeks|months|years)$')
    match = pattern.match(frequency)

    if not match:
        raise ValueError(f"Unrecognized unit in frequency string: {frequency}")

    number = int(match.group(1))
    unit = match.group(2)

    if unit == 'seconds':
        return datetime.timedelta(seconds=number)
    elif unit == 'minutes':
        return datetime.timedelta(minutes=number)
    elif unit == 'hours':
        return datetime.timedelta(hours=number)
    elif unit == 'days':
        return datetime.timedelta(days=number)
    elif unit == 'weeks':
        return datetime.timedelta(weeks=number)
    elif unit == 'months':
        # Use calendar to get the number of days in the given month
        current_date = datetime.datetime.now()
        days_in_month = (current_date.replace(month=current_date.month % 12 + 1, year=current_date.year + (current_date.month - 1) // 12) - datetime.timedelta(days=1)).day
        return datetime.timedelta(days=number * days_in_month)
    elif unit == 'years':
        # Use calendar to get the number of days in the given year
        current_date = datetime.datetime.now()
        days_in_year = 365 if not datetime.datetime.isleap(current_date.year) else 366
        return datetime.timedelta(days=number * days_in_year)
    else:
        raise ValueError(f"Unrecognized unit in frequency string: {frequency}")

