class Bookmarks:
    def __init__(self):
        self.categories = {}

    def add_bookmark(self, title: str, url: str, category: str):
        if category not in self.categories:
            self.categories[category] = []
        self.categories[category].append((title, url))

    def get_bookmarks(self):
        return self.categories

def from_raw_values(values: List[str]) -> Optional[Bookmarks]:
    """
    Create a Bookmarks object from a list of raw bookmark string values.
    Args:
        values (List[str]): A list of raw bookmark strings.
    Returns:
        Optional[Bookmarks]: A Bookmarks object or None if the input list is empty.
    """
    if not values:
        return None

    bookmarks = Bookmarks()
    for value in values:
        parts = value.split('|')
        if len(parts) == 3:
            title, url, category = parts
            bookmarks.add_bookmark(title.strip(), url.strip(), category.strip())
    return bookmarks
